// Decide whether anything has actually changed since the last look, and say
// so in words rather than in colours.
//
// Only transitions are reported. A page that emails every fifteen minutes
// while a disk is full is a page you filter into a folder and stop reading,
// and then it is worth nothing on the day it matters.

const WORSE = { green: 0, amber: 1, red: 2, grey: 1 };

// $input.first(), not the bare per-item shorthand: a Code node runs once for
// all items by default, where that shorthand is undefined. Getting it wrong
// fails at run time — which for a watchdog means failing silently, in the
// background, and looking exactly like "nothing is wrong".
const input = $input.first().json;
const body = input.body ?? input;
const fetched = typeof body === 'string' ? JSON.parse(body) : body;

// A watchdog that cannot see is itself a fault, and the one fault nothing
// else will report.
if (!fetched || !Array.isArray(fetched.parts)) {
  return [{ json: {
    changed: true,
    subject: 'Monitoring is not answering',
    html: `<p>The watchdog asked the monitoring page how things were and could
           not get an answer, so nothing is being checked right now.</p>
           <p>Status code: ${input.statusCode ?? 'none'}<br>
           This is the one failure the monitoring page cannot report itself.</p>
           <p><a href="https://dashboard.itsurgery.me/monitoring">Open it</a></p>`,
  } }];
}

// Static data survives between executions. It does not survive a redeploy of
// the workflow, so the first run after one re-learns the world in silence
// rather than emailing about things that were already true.
const store = $getWorkflowStaticData('global');
const previous = store.parts || null;
const now = {};
fetched.parts.forEach(p => { now[p.what] = p.state; });

if (!previous) {
  store.parts = now;
  return [{ json: { changed: false, learned: Object.keys(now).length } }];
}

const worsened = [];
const recovered = [];
const appeared = [];
const vanished = [];

fetched.parts.forEach(p => {
  const was = previous[p.what];
  if (was === undefined) { if (p.state !== 'green') appeared.push(p); return; }
  if (was === p.state) return;
  (WORSE[p.state] > WORSE[was] ? worsened : recovered)
    .push({ ...p, was });
});
Object.keys(previous).forEach(what => {
  if (!(what in now)) vanished.push({ what, was: previous[what] });
});

store.parts = now;

if (!worsened.length && !recovered.length && !appeared.length && !vanished.length) {
  return [{ json: { changed: false } }];
}

const line = (p) => `<li><strong>${p.what}</strong> — ${p.detail || ''}${
  p.was ? ` <span style="color:#5a6068">(was ${p.was})</span>` : ''}</li>`;

// Something that has only just appeared and is already unhealthy is a
// problem, not a recovery. Reading the subject line wrongly at a glance is
// the whole failure mode this is meant to avoid.
const bad = worsened.concat(appeared);
const andMore = (list) => list.length > 1 ? ` and ${list.length - 1} more` : '';
const worstNow = bad.reduce((w, p) => WORSE[p.state] > WORSE[w] ? p.state : w, 'green');

const subject =
    bad.length      ? `${worstNow === 'red' ? 'Problem' : 'Warning'} — ${bad[0].what}${andMore(bad)}`
  : vanished.length ? `No longer being checked — ${vanished[0].what}${andMore(vanished)}`
  :                   `Recovered — ${recovered[0].what}${andMore(recovered)}`;

const section = (title, items) => items.length
  ? `<p><strong>${title}</strong></p><ul>${items.map(line).join('')}</ul>` : '';

return [{ json: {
  changed: true,
  subject,
  html: `
    ${section('Gone wrong', worsened)}
    ${section('Back to normal', recovered)}
    ${section('New and not healthy', appeared)}
    ${section('Stopped being reported', vanished)}
    <p>Everything else is as it was. Overall: <strong>${fetched.overall}</strong>.</p>
    <p><a href="https://dashboard.itsurgery.me/monitoring">Open the monitoring page</a></p>`,
} }];
